svg.script:

const current = window.location.href;
let base = "https://esm.sh/gh/theofficalnothing-arch/securly@c4f9efe/";

if (current.includes("unpkg.com")) {
  base = "https://unpkg.com/securly-assets@1.0.1/";
} else if (current.includes("cdn.jsdelivr.net")) {
  base = "https://cdn.jsdelivr.net/gh/theofficalnothing-arch/securly@main/";
} else if (current.includes("raw.githubusercontent.com")) {
  base = "https://raw.githubusercontent.com/theofficalnothing-arch/securly/main/";
}

document.getElementById("duckmath").setAttribute("href", base + "duckmath.svg");
document.getElementById("securly").setAttribute("href", base + "securly.svg");
document.getElementById("opium").setAttribute("href", base + "svg/icon.svg");
